	CodeReleaseComparisonDataIncomplete      = "ReleaseComparisonDataIncomplete"
	CodeInvalidReleaseComparisonQuery        = "INVALID_RELEASE_COMPARISON_QUERY"
	CodeInvalidHistoryPagination             = "INVALID_HISTORY_PAGINATION"
	CodeInvalidChangeQueryV1                 = "INVALID_CHANGE_QUERY"
	CodeInvalidReleaseRecordQueryV1          = "INVALID_RELEASE_RECORD_QUERY"
)

// TrackedEnvironment is an environment that may receive release records.
type TrackedEnvironment struct {
	Environment  string
	DisplayName  string
	RegisteredAt string
}

// EnsureEnvironment registers an environment. It is idempotent: an existing
// environment is returned unchanged. New rows gain a server-generated
// registered_at timestamp.
func (s *Store) EnsureEnvironment(env *TrackedEnvironment) (created bool, err error) {
	res, err := s.db.Exec(
		`INSERT OR IGNORE INTO tracked_environments (environment, display_name) VALUES (?, ?)`,
		env.Environment, env.DisplayName,
	)
	if err != nil {
		return false, fmt.Errorf("store: ensure environment: %w", err)
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("store: ensure environment: %w", err)
	}
	created = affected > 0
	stored, err := s.GetEnvironment(env.Environment)
	if err != nil {
		return false, err
	}
	*env = *stored
	return created, nil
}

// GetEnvironment returns one registered environment, or (nil, nil) when the
// key is unknown.
func (s *Store) GetEnvironment(environment string) (*TrackedEnvironment, error) {
	row := s.db.QueryRow(
		`SELECT environment, display_name, registered_at FROM tracked_environments WHERE environment = ?`,
		environment,
	)
	var env TrackedEnvironment
	if err := row.Scan(&env.Environment, &env.DisplayName, &env.RegisteredAt); err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, fmt.Errorf("store: get environment: %w", err)
	}
	return &env, nil
}

// TrackedEnvironmentExists reports whether the environment key is registered.
func (s *Store) TrackedEnvironmentExists(environment string) (bool, error) {
	var count int
	if err := s.db.QueryRow(
		`SELECT count(1) FROM tracked_environments WHERE environment = ?`, environment,
	).Scan(&count); err != nil {
		return false, fmt.Errorf("store: check tracked environment: %w", err)
	}
	return count > 0, nil
}

// ListEnvironments returns every registered environment ordered by key.
func (s *Store) ListEnvironments() ([]TrackedEnvironment, error) {
	rows, err := s.db.Query(
		`SELECT environment, display_name, registered_at FROM tracked_environments ORDER BY environment ASC`,
	)
	if err != nil {
		return nil, fmt.Errorf("store: list environments: %w", err)
	}
	defer rows.Close()
	environments := []TrackedEnvironment{}
	for rows.Next() {
		var env TrackedEnvironment
		if err := rows.Scan(&env.Environment, &env.DisplayName, &env.RegisteredAt); err != nil {
			return nil, fmt.Errorf("store: list environments: %w", err)
		}
		environments = append(environments, env)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list environments: %w", err)
	}
	return environments, nil
}
package store

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
)

// Release is one immutable release record. Records created before change
// tracking was added carry nil Changes, GateStatus and RollbackPoint; readers
// must treat those as "field not present" rather than invalid.
type Release struct {
	ID            int64
	Name          string
	Environment   string
	Version       string
	Changes       []string
	GateStatus    *string
	RollbackPoint *string
	CreatedAt     string
}

// ReleaseFilter narrows ListReleases. The zero value matches every record.
type ReleaseFilter struct {
	Environment   string
	Version       string
	Change        string
	GateStatus    string
	RollbackPoint string
}

const releaseColumns = `id, name, environment, version, changes_json, gate_status, rollback_point, created_at`

// InsertRelease stores a new release record and fills in ID and CreatedAt.
func (s *Store) InsertRelease(rel *Release) error {
	changesJSON, err := json.Marshal(rel.Changes)
	if err != nil {
		return fmt.Errorf("store: encode changes: %w", err)
	}
	res, err := s.db.Exec(
		`INSERT INTO deployments (name, environment, version, changes_json, gate_status, rollback_point)
		 VALUES (?, ?, ?, ?, ?, ?)`,
		rel.Name, rel.Environment, rel.Version, string(changesJSON), rel.GateStatus, rel.RollbackPoint,
	)
	if err != nil {
		return fmt.Errorf("store: insert release: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return fmt.Errorf("store: insert release: %w", err)
	}
	rel.ID = id
	return s.db.QueryRow(`SELECT created_at FROM deployments WHERE id = ?`, id).Scan(&rel.CreatedAt)
}

// FindRelease returns the effective record for an environment and version: the
// one registered last. It returns (nil, nil) when no such record exists.
func (s *Store) FindRelease(environment, version string) (*Release, error) {
	row := s.db.QueryRow(
		`SELECT `+releaseColumns+` FROM deployments
		 WHERE environment = ? AND version = ?
		 ORDER BY id DESC LIMIT 1`,
		environment, version,
	)
	rel, err := scanRelease(row)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("store: find release: %w", err)
	}
	return rel, nil
}

// ListReleases returns every record matching the filter in registration order
// (oldest first). An empty result is an empty slice, never nil.
func (s *Store) ListReleases(filter ReleaseFilter) ([]Release, error) {
	var where []string
	var args []any
	if filter.Environment != "" {
		where = append(where, `environment = ?`)
		args = append(args, filter.Environment)
	}
	if filter.Version != "" {
		where = append(where, `version = ?`)
		args = append(args, filter.Version)
	}
	if filter.Change != "" {
		where = append(where, `changes_json IS NOT NULL AND EXISTS (SELECT 1 FROM json_each(deployments.changes_json) WHERE json_each.value = ?)`)
		args = append(args, filter.Change)
	}
	if filter.GateStatus != "" {
		where = append(where, `gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.RollbackPoint != "" {
		where = append(where, `rollback_point = ?`)
		args = append(args, filter.RollbackPoint)
	}
	query := `SELECT ` + releaseColumns + ` FROM deployments`
	if len(where) > 0 {
		query += ` WHERE ` + strings.Join(where, ` AND `)
	}
	query += ` ORDER BY id ASC`
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("store: list releases: %w", err)
	}
	defer rows.Close()
	releases := []Release{}
	for rows.Next() {
		rel, err := scanRelease(rows)
		if err != nil {
			return nil, fmt.Errorf("store: list releases: %w", err)
		}
		releases = append(releases, *rel)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list releases: %w", err)
	}
	return releases, nil
}

// EnvironmentExists reports whether any release record names the environment.
func (s *Store) EnvironmentExists(environment string) (bool, error) {
	var count int
	if err := s.db.QueryRow(`SELECT count(1) FROM deployments WHERE environment = ?`, environment).Scan(&count); err != nil {
		return false, fmt.Errorf("store: check environment: %w", err)
	}
	return count > 0, nil
}

// scanRelease reads one row from anything that behaves like sql.Row or sql.Rows.
func scanRelease(row interface{ Scan(...any) error }) (*Release, error) {
	var rel Release
	var changesJSON, gateStatus, rollbackPoint sql.NullString
	err := row.Scan(&rel.ID, &rel.Name, &rel.Environment, &rel.Version, &changesJSON, &gateStatus, &rollbackPoint, &rel.CreatedAt)
	if err != nil {
		return nil, err
	}
	if changesJSON.Valid {
		var changes []string
		if err := json.Unmarshal([]byte(changesJSON.String), &changes); err != nil {
			return nil, fmt.Errorf("store: decode changes: %w", err)
		}
		rel.Changes = changes
	}
	if gateStatus.Valid {
		value := gateStatus.String
		rel.GateStatus = &value
	}
	if rollbackPoint.Valid {
		value := rollbackPoint.String
		rel.RollbackPoint = &value
	}
	return &rel, nil
}

